#!/bin/bash
# docs/reports/audit_step.md §4.7's five isolation variants, on the primary MNIST auto-encoder
# bench, before any learning-rate sweep (§4.7's own ordering: "until they are done the quantity
# being swept is not well defined"). Hand-written, not generated by generate_jobs.py (that script
# enumerates the model registry and registered sweeps, not one-off audit experiments).
#
# Each config below is one bench invocation (fixed epoch count, no WCT confound, so every arm of
# every config gets exactly the same number of steps and configs are directly comparable to each
# other): baseline (today's implemented rule, unchanged); the corrected Eq. (3) average alone
# (--gamma 0.8); diag's min-max moved to Algorithm 1's order alone (--minmax-after-average); both
# corrections together on diag (completes the 2x2 audit_step.md §4.7 asks for); TCov=1 under both
# the corrected and the uncorrected average (isolates TCov alone, and its interaction with the
# corrected rule). Six configs x up to five arms = 22 arm-runs total, comparable in scale to the
# existing 3-value/7-arm --lam sweep (sweep_mnist_autoencoder_lam.sh, 00:20:00) that this script's
# time budget is set from.
#
# Submit from the repository root:  sbatch benchmarks/slurm/mnist/audit_step_ema_correction.sh

#SBATCH --account=def-msh-ab
#SBATCH --job-name=mnist_autoencoder_ema_audit
#SBATCH --gpus=h100_1g.10gb:1
#SBATCH --cpus-per-task=8
#SBATCH --mem=16G
#SBATCH --time=00:45:00
#SBATCH --output=benchmarks/slurm/logs/%x-%j.out

set -euo pipefail
cd "$SLURM_SUBMIT_DIR"

module purge
module load StdEnv/2023 gcc/13.3 cuda/12.6 python/3.11.5

virtualenv --no-download "$SLURM_TMPDIR/env"
source "$SLURM_TMPDIR/env/bin/activate"
pip install --no-index --upgrade pip
pip install --no-index -r requirements-cluster.txt

export PYTHONPATH="$SLURM_SUBMIT_DIR/src:$SLURM_SUBMIT_DIR"
DATA_ROOT="${DATA_ROOT:-$SLURM_SUBMIT_DIR/dataset}"
OUT="$SLURM_SUBMIT_DIR/benchmarks/outputs/sweeps/mnist_autoencoder_ema_audit"
COMMON=(--epochs 20 --budget-mode epochs --num-workers 8 --no-allow-download
        --data-root "$DATA_ROOT" --no-plot)

echo "=== A: baseline (today's implemented rule, unchanged) ==="
python -m benchmarks.models.mnist_autoencoder.bench \
  --arms diag kfac ekfac tkfac tekfac "${COMMON[@]}" \
  --output-dir "$OUT/A_baseline"

echo "=== B: Eq. (3) corrected average (--gamma 0.8), all five modes ==="
python -m benchmarks.models.mnist_autoencoder.bench \
  --arms diag kfac ekfac tkfac tekfac "${COMMON[@]}" \
  --gamma 0.8 \
  --output-dir "$OUT/B_gamma_corrected"

echo "=== C: diag, min-max after the average (Algorithm 1's order), uncorrected gamma ==="
python -m benchmarks.models.mnist_autoencoder.bench \
  --arms diag "${COMMON[@]}" \
  --minmax-after-average \
  --output-dir "$OUT/C_diag_minmax_after"

echo "=== D: diag, both corrections at once (completes the 2x2 with A/B/C) ==="
python -m benchmarks.models.mnist_autoencoder.bench \
  --arms diag "${COMMON[@]}" \
  --gamma 0.8 --minmax-after-average \
  --output-dir "$OUT/D_diag_both_corrected"

echo "=== E: TCov=1, corrected average (Algorithm 1 recomputes every step) ==="
python -m benchmarks.models.mnist_autoencoder.bench \
  --arms diag kfac ekfac tkfac tekfac "${COMMON[@]}" \
  --gamma 0.8 --tcov 1 \
  --output-dir "$OUT/E_tcov1_gamma_corrected"

echo "=== F: TCov=1, today's implemented (uncorrected) average, for reference ==="
python -m benchmarks.models.mnist_autoencoder.bench \
  --arms diag kfac ekfac tkfac tekfac "${COMMON[@]}" \
  --tcov 1 \
  --output-dir "$OUT/F_tcov1_baseline"
